import com.comsol.model.*;import com.comsol.model.util.*;import com.comsol.model.physics.*;import java.util.*;import java.io.*;
public class BinaryStreamSolveV3{
 static String fuel="(y>0.00131[m])";
 static String old(String e){return "withsol('binaryWarm',("+e+"))";}
 public static void main(String[] a){try{ModelUtil.initStandalone(false);ModelUtil.showPlots(false);ModelUtil.showProgress(a[2]);Model m=ModelUtil.load("BinaryStream",a[0]);m.sol("sol1").copySolution("binaryWarm");
  m.component("comp1").physics().create("tbin","ConcentratedSpecies","geom1",new String[]{"bA","bB"});m.physics("tbin").selection().set(new int[]{1,2,4,5});m.physics("tbin").prop("SpeciesProperties").set("FromMassConstraint","2");m.physics("tbin").prop("TransportMechanism").set("DiffusionModel","MaxwellStefan");m.physics("tbin").prop("TransportMechanism").set("MassTransferInPorousMedia",true);
  m.physics("tbin").prop("MassConsistentStabilization").set("massStreamlineDiffusion",false);m.physics("tbin").prop("MassConsistentStabilization").set("massCrosswindDiffusion",false);
  m.physics("tbin").prop("ShapeProperty").set("order_massfraction",1);m.physics("tbin").prop("ShapeProperty").set("boundaryFlux_massfraction",true);m.physics("tbin").prop("ShapeProperty").set("boundaryFluxSmooth_massfraction",false);
  m.physics("tbin").feature("sp1").set("M_bA","if("+fuel+",M_H2,M_O2)");m.physics("tbin").feature("sp1").set("M_bB","if("+fuel+",M_H2O,M_N2)");
  m.physics("tbin").create("pom1","PorousMedium",2);m.physics("tbin").feature("pom1").selection().set(new int[]{2,4});m.physics("tbin").feature("pom1").feature("pm1").set("epsilon_p_mat","userdef");m.physics("tbin").feature("pom1").feature("pm1").set("epsilon_p","eps_p");
  for(PhysicsFeature f:new PhysicsFeature[]{m.physics("tbin").feature("cdm1"),m.physics("tbin").feature("pom1").feature("fluid1")}){
   f.set("u_src","userdef");f.set("u",new String[]{"u","v","0"});f.set("rho_src","IdealGas");f.set("minput_temperature_src","userdef");f.set("minput_temperature","T");f.set("minput_pressure_src","userdef");f.set("minput_pressure","p_ref");f.setIndex("Species1","bA",0);f.setIndex("Species2","bB",0);f.setIndex("DF","if("+fuel+",D12,D34)",0);
  }
  m.physics("tbin").feature("pom1").feature("fluid1").set("FluidDiffusivityModelType","TortuosityModel");m.physics("tbin").feature("pom1").feature("fluid1").set("tauF","tau_p");
  for(int k=0;k<2;k++){String tag="binIn"+k;m.physics("tbin").create(tag,"MassFraction",1);m.physics("tbin").feature(tag).selection().set(new int[]{k==0?1:9});m.physics("tbin").feature(tag).set("species",new int[]{1,0});m.physics("tbin").feature(tag).set("wbnd",new double[]{k==0?.21:.95,0});}
  m.physics("tbin").create("binOut","Outflow",1);m.physics("tbin").feature("binOut").selection().set(new int[]{12,16});
  m.physics("tbin").create("rxn_an","ReactionSources",2);m.physics("tbin").feature("rxn_an").selection().set(new int[]{4});m.physics("tbin").feature("rxn_an").set("R_bA","-alpha_rxn*cd.iloc_panr1*Av_an*M_H2/(2*F_const)");m.physics("tbin").feature("rxn_an").set("R_bB","alpha_rxn*cd.iloc_panr1*Av_an*M_H2O/(2*F_const)");
  m.physics("tbin").create("rxn_ca","ReactionSources",2);m.physics("tbin").feature("rxn_ca").selection().set(new int[]{2});m.physics("tbin").feature("rxn_ca").set("R_bA","alpha_rxn*cd.iloc_pcar1*Av_ca*M_O2/(4*F_const)");m.physics("tbin").feature("rxn_ca").set("R_bB","0[kg/(m^3*s)]");
  m.component("comp1").variable().create("binaryPhysical");m.component("comp1").variable("binaryPhysical").selection().geom("geom1",2);m.component("comp1").variable("binaryPhysical").selection().set(new int[]{1,2,4,5});
  String[] names={"H2","H2O","O2","N2"},vals={"if("+fuel+",bA,0)","if("+fuel+",bB,0)","if("+fuel+",0,bA)","if("+fuel+",0,bB)"},src={"if("+fuel+",tcs2.R_bA,0[kg/(m^3*s)])","if("+fuel+",tcs2.R_bB,0[kg/(m^3*s)])","if("+fuel+",0[kg/(m^3*s)],tcs2.R_bA)","if("+fuel+",0[kg/(m^3*s)],tcs2.R_bB)"};
  for(int k=0;k<4;k++){m.component("comp1").variable("binaryPhysical").set("bt_"+names[k],vals[k]);m.component("comp1").variable("binaryPhysical").set("bt_R"+(k+1),src[k]);}
  m.physics("fp").feature("fp1").set("rho","tcs2.rho");m.physics("fp").feature("porous1").feature("fluid1").set("rho","tcs2.rho");m.physics("fp").feature("massFaraday").set("Qm","tcs2.R_bA+tcs2.R_bB");m.physics("ht").feature("fluid1").set("rho","tcs2.rho");
  m.physics("siec").feature("pca1").feature("pcar1").set("ilim","4*F_const*D_eff_gas*(bt_O2*tcs2.rho/M_O2)/delta_mt");m.physics("siec").feature("pan1").feature("panr1").set("ilim","2*F_const*D_eff_gas*(bt_H2*tcs2.rho/M_H2)/delta_mt");
  for(String tag:new String[]{"lfSpecies","lfSpeciesPorts"})m.component("comp1").common(tag).active(false);
  for(PhysicsFeature f:new PhysicsFeature[]{m.physics("tbin").feature("cdm1"),m.physics("tbin").feature("pom1").feature("fluid1")})for(String[] row:f.featureInfo("info").getInfoTable("Weak"))if(!row[1].contains("cbf_"))f.featureInfo("info").set(row[2],new String[]{"0"});
  LFPrimaryConservative.weak(m,"binarySpecies",2,new int[]{1,2,4,5},"((tcs2.j_bAx+fp.rho*u*bA)*test(bAx)+(tcs2.j_bAy+fp.rho*v*bA)*test(bAy)+tcs2.R_bA*test(bA))*tcs2.d");LFPrimaryConservative.weak(m,"binarySpeciesPorts",1,new int[]{1,9,12,16},"-fp.rho*bA*(u*nx+v*ny)*test(bA)*tcs2.d");
  m.physics("tbin").feature("init1").set("w0",new String[]{"if("+fuel+","+old("w1")+","+old("w3")+")","if("+fuel+","+old("w2")+","+old("w4")+")"});m.physics("fp").feature("init1").set("u_init",new String[]{old("u"),old("v"),"0"});m.physics("fp").feature("init1").set("p_init",old("p"));m.physics("ht").feature("init1").set("Tinit",old("T"));
  for(String tag:m.physics("siec").feature().tags())if(m.physics("siec").feature(tag).getType().equals("init")){m.physics("siec").feature(tag).set("phis",old("phis"));m.physics("siec").feature(tag).set("phil",old("phil"));}
  ArrayList<String> active=new ArrayList<>();for(String tag:m.physics().tags()){active.add(tag);active.add(tag.equals("tcs")?"off":"on");}m.study("std1").feature("stat").set("activate",active.toArray(new String[0]));m.sol("sol1").feature("v1").set("initmethod","init");m.sol("sol1").feature("v1").set("notsolmethod","sol");m.sol("sol1").feature("v1").set("notsol","binaryWarm");m.sol("sol1").feature("v1").updateVariables();
  m.sol("sol1").feature("v1").feature("comp1_bA").set("scalemethod","manual");m.sol("sol1").feature("v1").feature("comp1_bA").set("scaleval","0.2");m.sol("sol1").feature("s1").set("stol","1e-9");m.sol("sol1").feature("s1").feature("fc1").set("initstep","1");m.sol("sol1").feature("s1").feature("fc1").set("maxiter","30");m.sol("sol1").feature("s1").feature("fc1").set("termonres","off");
  m.label("Split binary Maxwell-Stefan conservative model; original four-species physics inactive for comparison");m.save(a[1].replace(".mph","_configured.mph"));System.out.println("BINARY_SOLVE_START");System.out.flush();m.sol("sol1").runAll();m.save(a[1]);m.save(a[1].replace(".mph","_history.java"),"java");System.out.println("BINARY_SOLVE_COMPLETE");System.exit(0);
 }catch(Throwable e){e.printStackTrace(System.out);System.exit(1);}}
}
